const raw = $input.item.json;
function extractText(obj) {
  if (typeof obj === 'string') return obj;
  if (obj && obj.text) return obj.text;
  if (obj && obj.content) return typeof obj.content === 'string' ? obj.content : ((obj.content.parts && obj.content.parts[0] && obj.content.parts[0].text) || '');
  if (obj && obj.candidates && obj.candidates[0] && obj.candidates[0].content && obj.candidates[0].content.parts && obj.candidates[0].content.parts[0]) return obj.candidates[0].content.parts[0].text;
  if (obj && obj.response && obj.response.text) return obj.response.text;
  return '';
}
const modelText = (extractText(raw) || '').trim();
const ALLOWED_CATEGORIES = ['Idea', 'Suggestion', 'Decision', 'Action Item', 'Question', 'Observation'];
const tg = $('Telegram Trigger').item.json.message;
if (!modelText || modelText.toUpperCase() === 'SKIP') {
  return { json: { is_valid: false, skipped: true, data: null, message: 'Model marked this message as not worth extracting.', raw_model_output: modelText } };
}
let cleaned = modelText;
if (cleaned.indexOf('```') === 0) {
  cleaned = cleaned.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
}
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return { json: { is_valid: false, skipped: false, data: null, message: 'Model output was not valid JSON (treated as a refusal, not an error).', raw_model_output: modelText } };
}
if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
  return { json: { is_valid: false, skipped: false, data: null, message: 'Model output was not a JSON object.', raw_model_output: modelText } };
}
const requiredStringFields = ['category', 'title', 'summary'];
const requiredArrayFields = ['key_points', 'tags', 'open_questions'];
for (const field of requiredStringFields) {
  if (typeof parsed[field] !== 'string' || !parsed[field].trim()) {
    return { json: { is_valid: false, skipped: false, data: null, message: 'Missing or invalid required field: ' + field, raw_model_output: modelText } };
  }
}
for (const field of requiredArrayFields) {
  if (!Array.isArray(parsed[field])) {
    return { json: { is_valid: false, skipped: false, data: null, message: 'Missing or invalid required field: ' + field, raw_model_output: modelText } };
  }
}
if (ALLOWED_CATEGORIES.indexOf(parsed.category) === -1) {
  return { json: { is_valid: false, skipped: false, data: null, message: 'Category "' + parsed.category + '" is not one of the allowed categories.', raw_model_output: modelText } };
}
return { json: { is_valid: true, skipped: false, message: 'ok', data: { category: parsed.category, title: parsed.title, summary: parsed.summary, key_points: parsed.key_points, tags: parsed.tags, open_questions: parsed.open_questions }, telegram_message_id: tg.message_id, telegram_chat_id: tg.chat.id, telegram_from: (tg.from && (tg.from.username || tg.from.first_name)) || 'unknown' } };
